"""Compare the original-pattern ablation with immutable robustness baselines."""
from pathlib import Path
from decimal import Decimal,ROUND_HALF_UP
import json,hashlib,csv,collections,datetime
ROOT=Path.cwd();BASE=ROOT/'results/real-app/robustness';OUT=BASE/'legacy-original-patterns-comparison';OUT.mkdir(exist_ok=True);CODE=ROOT/'scripts/real-app/robustness/legacy-patterns'
read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();pct=lambda x:str((Decimal(str(x))*100).quantize(Decimal('0.01'),rounding=ROUND_HALF_UP))+'%'
provenance=read(CODE/'provenance.json')
for f in provenance['files']:assert sha(CODE/'vendor'/f['name'])==f['sha256']
assert sha(CODE/'host.ts')==provenance['hostSha256'] and sha(CODE/'recognizer.cjs')==provenance['compiledRecognizerSha256']
# Assert that only the bundle recognition block and its import changed in the static solver.
frozen=(ROOT/'scripts/real-app/robustness/frozen-module-graph.mjs').read_text();adapted=(CODE/'adapted-module-graph.mjs').read_text().replace("import {recognize} from './recognize.mjs';\n",'')
start='  }else{\n';end='\n  function index';fa=frozen.index(start,frozen.index('if(spec.kind'));fb=frozen.index(end,fa);aa=adapted.index(start,adapted.index('if(spec.kind'));ab=adapted.index(end,aa)
assert frozen[:fa]==adapted[:aa] and frozen[fb:]==adapted[ab:]
rows=[];repos=[];files=[]
for slug in ['bailicangdu--vue2-elm','vuejs--vue-hackernews-2.0']:
 p=BASE/slug;q=p/'legacy-original-patterns';old=read(p/'summary.json');new=read(q/'summary.json');ot=read(p/'target-traces.json');nt=read(q/'target-traces.json');oldma=read(p/'module-analysis.json');newma=read(q/'module-analysis-per-chunk.json')
 assert old['commit']==new['commit'] and old['seedCounts']==new['seedCounts']
 assert read(p/'seed-audit.json')==read(q/'seed-audit.json')
 assert oldma['source']==newma['source']
 assert [(l['library'],l['supportedTargets']) for l in old['libraries']]==[(l['library'],l['supportedTargets']) for l in new['libraries']]
 for k,n in [('detectorInputSha256','detector-input.json'),('oracleSha256','ground-truth.json')]:assert old['provenance'][k]==new['provenance'][k]==sha(p/n)
 assert new['provenance']['extractorSha256']==sha(CODE/'adapted-module-graph.mjs') and new['provenance']['runnerSha256']==sha(CODE/'run.mjs')
 assert new['modelCalls']==0 and newma['bundle']['status']=='complete' and all(c['status']=='complete' and c['solver']['converged'] for c in newma['bundle']['chunkAnalysis'])
 assert old['aggregate']['original']==new['aggregate']['original']
 before={t['bundleId'] for t in ot if t['variant']=='frozen-intermodule' and t['recovered']};after={t['bundleId'] for t in nt if t['variant']=='original-patterns-intermodule' and t['recovered']};assert before<=after
 xs=[t for t in nt if t['variant']=='original-patterns-intermodule'];accepted={t['bundleId']:t for t in xs if t['recovered']}
 for t in accepted.values():
  if t['round']:
   parent=accepted[t['parentWitness']['bundleId']];assert parent['build']==t['build'] and parent['round']<t['round'] and parent['sourceId']==t['parentWitness']['sourceId']
 for l,nl in zip(old['libraries'],new['libraries']):
  b=l['variants']['frozen-intermodule'];a=nl['variants']['original-patterns-intermodule'];assert b['initialAnchors']==a['initialAnchors'];assert a['recovered']+a['unreached']==l['supportedTargets']
  rows.append({'repo':new['repo'],'mechanism':'webpack 1.15.0' if 'vue2-elm' in slug else 'webpack 3.11.0','library':l['library'],'targets':l['supportedTargets'],'before_recovered':b['recovered'],'before_rate':b['rate'],'after_recovered':a['recovered'],'after_rate':a['rate'],'additional_recovered':a['recovered']-b['recovered'],'improvement_percentage_points':100*(a['rate']-b['rate'])})
 br=newma['bundle'];recognition_count=len(br['chunkAnalysis']);repos.append({'repo':new['repo'],'commit':new['commit'],'libraries':len(new['libraries']),'recognizedTargetChunks':recognition_count,'bundleModuleInstances':len(br['modules']),'resolvedIntermoduleCallSites':len(br['functionEdges']),'before':old['aggregate']['frozen-intermodule'],'after':new['aggregate']['original-patterns-intermodule'],'additionalRecovered':len(after-before),'sourceGraphAndSeedsUnchanged':True})
 files.extend(q/n for n in ['summary.json','target-traces.json','module-analysis-per-chunk.json','seed-audit.json']);files.extend(p/n for n in ['summary.json','detector-input.json','ground-truth.json','module-analysis.json','seed-audit.json'])
with (OUT/'library-comparison.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
summary={'created':datetime.datetime.now(datetime.timezone.utc).isoformat(),'modelCalls':0,'artifact':provenance,'repos':repos,'libraryRows':len(rows),'changedLibraries':[r for r in rows if r['additional_recovered']],'policy':'Original authors webpackChunk patterns and isSubTree matcher, unchanged, with plain-JS parser/file host; original per-chunk radius-one oracle simulation and source binding analysis retained. No new seeds, initialization expansion, models, or top-K ranking.'};(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
text=['# Legacy webpack: original D-Bundlr recognition-pattern ablation','','The requested rerun reuses the authors’ original module-recognition pattern strings and AST subtree matcher. It recovers module boundaries in the tested webpack 1/3 artifacts and improves oracle connectivity. No model calls were made. Original robustness results are preserved.','','## Aggregate comparison','','| Repository | Bundler | Targets | Frozen extractor | Original recognition patterns | Additional targets |','|---|---|---:|---:|---:|---:|']
for r in repos:
 b=r['before'];a=r['after'];version='webpack 1.15.0' if 'vue2-elm' in r['repo'] else 'webpack 3.11.0';text.append(f"| {r['repo']} | {version} | {a['targets']} | {b['recovered']}/{b['targets']} ({pct(b['rate'])}) | {a['recovered']}/{a['targets']} ({pct(a['rate'])}) | +{r['additionalRecovered']} |")
text+=['','## Per-library comparison','']
for r in repos:
 text += [f"### {r['repo']}",'',f"Commit `{r['commit']}`. Original patterns recognize {r['recognizedTargetChunks']} target-containing chunks, {r['bundleModuleInstances']} module instances, and {r['resolvedIntermoduleCallSites']} singleton modeled inter-module call sites.",'','| Library | Targets | Frozen extractor | Original patterns | Additional targets |','|---|---:|---:|---:|---:|']
 for l in rows:
  if l['repo']==r['repo']:text.append(f"| {l['library']} | {l['targets']} | {l['before_recovered']}/{l['targets']} ({pct(l['before_rate'])}) | {l['after_recovered']}/{l['targets']} ({pct(l['after_rate'])}) | +{l['additional_recovered']} |")
 text+=['']
text += ['## What was reused and what stayed fixed','','- Pinned authors’ artifact: `https://github.com/Anemone95/D-Bundlr`, commit `c28a5d62efeecc46cc146c3548c71b8071ba2e89`. `webpackfingerprint.ts` and `subASTSearch.ts` are copied byte-for-byte. File hashes are in the adapter provenance.','- Reuse all original `webpackChunk` recognition patterns and the original `isSubTree` matcher. All eleven selected chunks match the authors’ `chunk999` legacy `webpackJsonp(...)` pattern. The original chunk whole-file start/end position gate is also retained. The captured module table is decoded as either an object or an array, preserving sparse-array indices as module IDs.','- A minimal Babel parser/in-memory text host replaces the artifact’s parser/logging/files dependencies. It parses these plain-JavaScript chunks without the authors’ TypeScript/template-literal desugaring pipeline. This is not execution of the complete original detector, predictor, dynamic validation, transformer, or Jelly solver.','- The captured factory spans are mapped to the existing Meriyah AST by exact start/end offsets. The static binding/value-flow solver differs from the frozen code only in its module-recognition block and the recognizer import. Original source-side module-analysis output is reused exactly.','- Keep the same source inputs, source-map labels, library selection, target denominators, POG seeds, per-chunk recovery boundary, radius one, sibling window two, size limit, strict source-identity policy, and synchronous oracle promotion rule. True counterparts are selected anywhere in the eligible neighborhood. No model ranking/validation, cached judgments, extra anchors, export-slot seed proposals, or initialization/module-membership expansion.','- Scope module IDs to each chunk analysis. Legacy numeric IDs recur across the saved chunks with different factory contents, so pooling all chunk module tables into one namespace would collide. Per-chunk extraction preserves the baseline recovery boundary; cross-chunk propagation is not added. A failed global-map attempt is retained in the webpack 1 output as `diagnostic-global-map-collision.json` and is not part of the final result.','', '## Findings','','The original recognition patterns eliminate the particular legacy-format gap introduced by our simplified extractor. In webpack 1, all 113 additional recoveries are core-js functions. In webpack 3, the 33 additional recoveries consist of 29 `@firebase/database` functions and four `@firebase/util` functions. Other selected libraries are unchanged.','','Successful recognition does not by itself connect every function. Several small libraries remain at zero with the unchanged seed/propagation rules. These results establish improved connectivity on the two pinned builds, not general support for all versions/configurations or an end-to-end evaluation of D-Bundlr. Vite was not changed or rerun in this ablation.','','## Verification and reproduction','','Six focused adapter tests passed: sparse array IDs, numeric object keys, namespace rejection, original chunk-position gate, exact factory spans and resolved imported calls, and unresolved-import abstention. The existing simulation independently verifies every fixed point against BFS on the paired source/bundle correspondence graph. Report verification checks that source analysis, seed audits, input hashes, and denominators match the frozen baseline, that accepted parent witnesses precede promotions, and that recovered sets grow monotonically.','','From the workspace root:','','```sh','node scripts/real-app/robustness/legacy-patterns/build-host.mjs','node --test scripts/real-app/robustness/legacy-patterns/recognize.test.mjs','node --max-old-space-size=8192 scripts/real-app/robustness/legacy-patterns/run.mjs bailicangdu--vue2-elm','node --max-old-space-size=8192 scripts/real-app/robustness/legacy-patterns/run.mjs vuejs--vue-hackernews-2.0','python3 scripts/real-app/robustness/legacy-patterns/report.py','```','','The per-repository `legacy-original-patterns/` folders contain the new module analysis, seed audit, round summaries, and per-target promotion traces. This comparison folder contains `library-comparison.csv`, `summary.json`, and `verification.json`. Rates count supported generated-function cases, including copies across chunks, exactly as in the frozen benchmark.','']
(OUT/'REPORT.md').write_text('\n'.join(text))
# Earlier benchmark files remain exactly as recorded before this ablation.
baseline=read(BASE/'verification.json')
for f,h in baseline['fileSha256'].items():assert sha(ROOT/f)==h
files+=list(CODE.glob('*'));files+=list((CODE/'vendor').glob('*'));files += [OUT/'REPORT.md',OUT/'summary.json',OUT/'library-comparison.csv']
v={'created':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'passed','modelCalls':0,'adapterFocusedTestsPassed':6,'originalPatternsAndMatcherByteIdentical':True,'sourceAnalysisAndSeedAuditsUnchanged':True,'frozenBenchmarkAllHashesUnchanged':True,'fixedPointsVerifiedByIndependentPairedGraphBfs':True,'fileSha256':{str(p.relative_to(ROOT)):sha(p) for p in files if p.is_file()}}
(OUT/'verification.json').write_text(json.dumps(v,indent=2)+'\n');print(json.dumps({'status':'passed','repos':repos,'changedLibraries':summary['changedLibraries']},indent=2))
